{"content": "/**
 * Main CSS - Common styles for the Michelin Capstone application
 * Following Michelin Design System color scheme
 */

/* CSS Variables - Michelin Design System Colors */
:root {
    /* Primary Colors */
    --michelin-blue: #27509b;
    --michelin-yellow: #fce500;
    --michelin-white: #ffffff;
    --michelin-black: #000000;

    /* Secondary Colors */
    --michelin-dark-blue: #1a3a6e;
    --michelin-light-blue: #4a7cc9;
    --michelin-gray-dark: #333333;
    --michelin-gray-medium: #666666;
    --michelin-gray-light: #cccccc;
    --michelin-gray-lighter: #f5f5f5;

    /* Semantic Colors */
    --color-success: #28a745;
    --color-warning: #ffc107;
    --color-error: #dc3545;
    --color-info: #17a2b8;

    /* Typography */
    --font-primary: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    --font-size-base: 16px;
    --font-size-small: 14px;
    --font-size-large: 18px;
    --font-size-h1: 32px;
    --font-size-h2: 24px;
    --font-size-h3: 20px;

    /* Spacing */
    --spacing-xs: 4px;
    --spacing-sm: 8px;
    --spacing-md: 16px;
    --spacing-lg: 24px;
    --spacing-xl: 32px;

    /* Border Radius */
    --border-radius-sm: 4px;
    --border-radius-md: 8px;
    --border-radius-lg: 12px;

    /* Shadows */
    --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.12);
    --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.1);
    --shadow-lg: 0 10px 20px rgba(0, 0, 0, 0.15);

    /* Navigation */
    --nav-width: 250px;
    --nav-width-collapsed: 60px;
    --header-height: 60px;
}

/* Reset and Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    font-size: var(--font-size-base);
}

body {
    font-family: var(--font-primary);
    background-color: var(--michelin-gray-lighter);
    color: var(--michelin-gray-dark);
    line-height: 1.6;
    min-height: 100vh;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
    color: var(--michelin-dark-blue);
    margin-bottom: var(--spacing-md);
}

h1 { font-size: var(--font-size-h1); }
h2 { font-size: var(--font-size-h2); }
h3 { font-size: var(--font-size-h3); }

p {
    margin-bottom: var(--spacing-md);
}

a {
    color: var(--michelin-blue);
    text-decoration: none;
}

a:hover {
    text-decoration: underline;
}

/* Buttons */
.btn-primary,
.btn-secondary {
    display: inline-block;
    padding: var(--spacing-sm) var(--spacing-lg);
    border: none;
    border-radius: var(--border-radius-sm);
    font-size: var(--font-size-base);
    cursor: pointer;
    transition: all 0.3s ease;
}

.btn-primary {
    background-color: var(--michelin-blue);
    color: var(--michelin-white);
}

.btn-primary:hover {
    background-color: var(--michelin-dark-blue);
}

.btn-secondary {
    background-color: var(--michelin-gray-light);
    color: var(--michelin-gray-dark);
}

.btn-secondary:hover {
    background-color: var(--michelin-gray-medium);
    color: var(--michelin-white);
}

/* Form Elements */
.form-group {
    margin-bottom: var(--spacing-md);
}

.form-group label {
    display: block;
    margin-bottom: var(--spacing-xs);
    font-weight: 600;
    color: var(--michelin-gray-dark);
}

.form-group input,
.form-group select,
.form-group textarea {
    width: 100%;
    padding: var(--spacing-sm) var(--spacing-md);
    border: 1px solid var(--michelin-gray-light);
    border-radius: var(--border-radius-sm);
    font-size: var(--font-size-base);
    transition: border-color 0.3s ease;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
    outline: none;
    border-color: var(--michelin-blue);
}

/* Tables */
.table-container {
    overflow-x: auto;
    background-color: var(--michelin-white);
    border-radius: var(--border-radius-md);
    box-shadow: var(--shadow-sm);
}

table {
    width: 100%;
    border-collapse: collapse;
}

thead {
    background-color: var(--michelin-blue);
    color: var(--michelin-white);
}

th, td {
    padding: var(--spacing-md);
    text-align: left;
    border-bottom: 1px solid var(--michelin-gray-light);
}

tbody tr:hover {
    background-color: var(--michelin-gray-lighter);
}

/* Cards */
.card {
    background-color: var(--michelin-white);
    border-radius: var(--border-radius-md);
    box-shadow: var(--shadow-sm);
    padding: var(--spacing-lg);
    margin-bottom: var(--spacing-md);
}

/* Page Layout */
.page-header {
    padding: var(--spacing-lg);
    background-color: var(--michelin-white);
    border-bottom: 1px solid var(--michelin-gray-light);
    margin-bottom: var(--spacing-lg);
}

/* Utility Classes */
.text-center { text-align: center; }
.text-right { text-align: right; }
.mt-1 { margin-top: var(--spacing-sm); }
.mt-2 { margin-top: var(--spacing-md); }
.mt-3 { margin-top: var(--spacing-lg); }
.mb-1 { margin-bottom: var(--spacing-sm); }
.mb-2 { margin-bottom: var(--spacing-md); }
.mb-3 { margin-bottom: var(--spacing-lg); }
.hidden { display: none; }

/* Messages */
.form-error,
.form-message {
    padding: var(--spacing-sm) var(--spacing-md);
    border-radius: var(--border-radius-sm);
    margin-top: var(--spacing-md);
}

.form-error {
    background-color: #f8d7da;
    color: var(--color-error);
    border: 1px solid var(--color-error);
}

.form-message.success {
    background-color: #d4edda;
    color: var(--color-success);
    border: 1px solid var(--color-success);
}
