{"content": "/**
 * Navigation CSS - Styles for the collapsible navigation bar
 */

/* Navigation Bar */
#navigation-bar {
    position: fixed;
    top: 0;
    left: 0;
    width: var(--nav-width);
    height: 100vh;
    background-color: var(--michelin-dark-blue);
    color: var(--michelin-white);
    z-index: 1000;
    transition: width 0.3s ease;
    overflow-x: hidden;
}

#navigation-bar.collapsed {
    width: var(--nav-width-collapsed);
}

/* Navigation Header */
.nav-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--spacing-md);
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.nav-logo {
    /* Logo styles */
}

.nav-toggle {
    background: none;
    border: none;
    color: var(--michelin-white);
    cursor: pointer;
    padding: var(--spacing-sm);
}

/* Navigation Menu */
.nav-menu {
    list-style: none;
    padding: var(--spacing-md) 0;
}

.nav-item {
    /* Navigation item styles */
}

.nav-link {
    display: flex;
    align-items: center;
    padding: var(--spacing-md);
    color: var(--michelin-white);
    text-decoration: none;
    transition: background-color 0.3s ease;
}

.nav-link:hover {
    background-color: var(--michelin-blue);
    text-decoration: none;
}

.nav-link.active {
    background-color: var(--michelin-blue);
    border-left: 4px solid var(--michelin-yellow);
}

.nav-icon {
    margin-right: var(--spacing-md);
    width: 24px;
    text-align: center;
}

.nav-text {
    white-space: nowrap;
    opacity: 1;
    transition: opacity 0.3s ease;
}

#navigation-bar.collapsed .nav-text {
    opacity: 0;
}

/* Profile Icon Container */
#profile-icon-container {
    position: fixed;
    top: var(--spacing-md);
    right: var(--spacing-md);
    z-index: 1001;
}

.profile-icon {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background-color: var(--michelin-blue);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.3s ease;
}

.profile-icon:hover {
    background-color: var(--michelin-dark-blue);
    box-shadow: var(--shadow-md);
}

.profile-icon img {
    width: 100%;
    height: 100%;
    border-radius: 50%;
    object-fit: cover;
}

/* Main Content Adjustment */
body:not(.no-nav) main {
    margin-left: var(--nav-width);
    padding: var(--spacing-lg);
    transition: margin-left 0.3s ease;
}

body:not(.no-nav).nav-collapsed main {
    margin-left: var(--nav-width-collapsed);
}

/* Responsive Design */
@media (max-width: 768px) {
    #navigation-bar {
        transform: translateX(-100%);
    }

    #navigation-bar.open {
        transform: translateX(0);
    }

    body:not(.no-nav) main {
        margin-left: 0;
    }

    .mobile-nav-toggle {
        display: block;
        position: fixed;
        top: var(--spacing-md);
        left: var(--spacing-md);
        z-index: 1002;
    }
}
