{"content": "/**
 * Landing Page CSS - Styles for the landing/welcome page
 */

.landing-page {
    /* Page layout */
}

.welcome-section {
    text-align: center;
    padding: var(--spacing-xl);
    background-color: var(--michelin-white);
    border-radius: var(--border-radius-md);
    box-shadow: var(--shadow-sm);
    margin-bottom: var(--spacing-xl);
}

.welcome-section h1 {
    font-size: 2.5rem;
    color: var(--michelin-dark-blue);
    margin-bottom: var(--spacing-md);
}

.welcome-section .user-name {
    color: var(--michelin-blue);
    font-weight: 700;
}

.welcome-section p {
    color: var(--michelin-gray-medium);
    font-size: var(--font-size-large);
}

/* Quick Links Section */
.quick-links {
    padding: var(--spacing-lg);
}

.quick-links h2 {
    margin-bottom: var(--spacing-lg);
}

.quick-links-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-lg);
}

.quick-link-card {
    background-color: var(--michelin-white);
    border-radius: var(--border-radius-md);
    box-shadow: var(--shadow-sm);
    padding: var(--spacing-xl);
    text-align: center;
    transition: all 0.3s ease;
    text-decoration: none;
    color: inherit;
}

.quick-link-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-md);
    text-decoration: none;
}

.quick-link-card .icon {
    font-size: 2.5rem;
    color: var(--michelin-blue);
    margin-bottom: var(--spacing-md);
}

.quick-link-card h3 {
    color: var(--michelin-dark-blue);
    margin-bottom: var(--spacing-sm);
}

.quick-link-card p {
    color: var(--michelin-gray-medium);
    font-size: var(--font-size-small);
    margin-bottom: 0;
}

/* Responsive Design */
@media (max-width: 768px) {
    .welcome-section h1 {
        font-size: 1.75rem;
    }

    .quick-links-grid {
        grid-template-columns: 1fr;
    }
}
