{"content": "/**
 * Dashboard CSS - Styles for the dashboard page
 */

.dashboard-page {
    /* Page layout */
}

.dashboard-page .page-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

/* Data Table Section */
.data-table-section {
    background-color: var(--michelin-white);
    border-radius: var(--border-radius-md);
    box-shadow: var(--shadow-sm);
    padding: var(--spacing-lg);
    margin-bottom: var(--spacing-xl);
}

.data-table-section h2 {
    margin-bottom: var(--spacing-lg);
    color: var(--michelin-dark-blue);
}

#data-table {
    /* Data table specific styles */
}

#data-table th {
    background-color: var(--michelin-blue);
}

/* API Usage Section */
.api-usage-section {
    background-color: var(--michelin-white);
    border-radius: var(--border-radius-md);
    box-shadow: var(--shadow-sm);
    padding: var(--spacing-lg);
}

.api-usage-section h2 {
    margin-bottom: var(--spacing-lg);
    color: var(--michelin-dark-blue);
}

/* Date Range Selector */
.date-range-selector {
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
    margin-bottom: var(--spacing-lg);
    flex-wrap: wrap;
}

.date-range-selector label {
    font-weight: 600;
    color: var(--michelin-gray-dark);
}

.date-range-selector input[type="date"] {
    padding: var(--spacing-sm) var(--spacing-md);
    border: 1px solid var(--michelin-gray-light);
    border-radius: var(--border-radius-sm);
}

/* API Stats Container */
.api-stats-container {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-lg);
    margin-bottom: var(--spacing-lg);
}

.stat-card {
    background-color: var(--michelin-gray-lighter);
    border-radius: var(--border-radius-md);
    padding: var(--spacing-lg);
    text-align: center;
    border-left: 4px solid var(--michelin-blue);
}

.stat-card h3 {
    color: var(--michelin-gray-medium);
    font-size: var(--font-size-small);
    text-transform: uppercase;
    margin-bottom: var(--spacing-sm);
}

.stat-card span {
    font-size: 2rem;
    font-weight: 700;
    color: var(--michelin-dark-blue);
}

/* API Breakdown */
.api-breakdown {
    margin-top: var(--spacing-lg);
}

.api-breakdown h3 {
    margin-bottom: var(--spacing-md);
}

#api-breakdown-chart {
    min-height: 200px;
    background-color: var(--michelin-gray-lighter);
    border-radius: var(--border-radius-sm);
    padding: var(--spacing-md);
}

/* Responsive Design */
@media (max-width: 768px) {
    .date-range-selector {
        flex-direction: column;
        align-items: flex-start;
    }

    .api-stats-container {
        grid-template-columns: 1fr;
    }
}
