{"content": "/**
 * Audit Log CSS - Styles for the audit log page
 */

.audit-log-page {
    /* Page layout */
}

.audit-log-page .page-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

/* Audit Log Section */
.audit-log-section {
    background-color: var(--michelin-white);
    border-radius: var(--border-radius-md);
    box-shadow: var(--shadow-sm);
    padding: var(--spacing-lg);
}

/* Audit Log Table */
#audit-log-table {
    /* Table specific styles */
}

#audit-log-table th {
    background-color: var(--michelin-blue);
    font-weight: 600;
}

#audit-log-table td {
    vertical-align: middle;
}

/* Action Type Badges */
.action-badge {
    display: inline-block;
    padding: var(--spacing-xs) var(--spacing-sm);
    border-radius: var(--border-radius-sm);
    font-size: var(--font-size-small);
    font-weight: 600;
    text-transform: uppercase;
}

.action-badge.login {
    background-color: #d4edda;
    color: var(--color-success);
}

.action-badge.logout {
    background-color: #f8d7da;
    color: var(--color-error);
}

.action-badge.update {
    background-color: #fff3cd;
    color: var(--color-warning);
}

.action-badge.view {
    background-color: #d1ecf1;
    color: var(--color-info);
}

/* Timestamp Column */
.timestamp-cell {
    white-space: nowrap;
    color: var(--michelin-gray-medium);
    font-size: var(--font-size-small);
}

/* Details Column */
.details-cell {
    max-width: 300px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.details-cell:hover {
    white-space: normal;
    word-wrap: break-word;
}

/* Pagination */
.pagination {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: var(--spacing-sm);
    margin-top: var(--spacing-lg);
    padding-top: var(--spacing-lg);
    border-top: 1px solid var(--michelin-gray-light);
}

.pagination button,
.pagination a {
    padding: var(--spacing-sm) var(--spacing-md);
    border: 1px solid var(--michelin-gray-light);
    border-radius: var(--border-radius-sm);
    background-color: var(--michelin-white);
    color: var(--michelin-gray-dark);
    cursor: pointer;
    transition: all 0.3s ease;
}

.pagination button:hover,
.pagination a:hover {
    background-color: var(--michelin-blue);
    color: var(--michelin-white);
    border-color: var(--michelin-blue);
}

.pagination .active {
    background-color: var(--michelin-blue);
    color: var(--michelin-white);
    border-color: var(--michelin-blue);
}

.pagination .disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Responsive Design */
@media (max-width: 768px) {
    .audit-log-section {
        padding: var(--spacing-md);
    }

    #audit-log-table th,
    #audit-log-table td {
        padding: var(--spacing-sm);
        font-size: var(--font-size-small);
    }

    .details-cell {
        max-width: 150px;
    }
}
