{"content": "/**
 * 404 Page CSS - Styles for the error page
 */

.error-page {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    background: linear-gradient(135deg, var(--michelin-gray-lighter), var(--michelin-white));
}

.error-container {
    text-align: center;
    padding: var(--spacing-xl);
}

.error-code h1 {
    font-size: 8rem;
    font-weight: 700;
    color: var(--michelin-blue);
    margin-bottom: 0;
    line-height: 1;
}

.error-message {
