/**
 * Get current page filename from URL
 * @returns {string} Current page filename
 */
function getCurrentPage() {
    const path = window.location.pathname;
    const page = path.substring(path.lastIndexOf('/') + 1) || 'index.html';
    return page;
}

/**
 * Generate the navigation bar HTML
 * @returns {string} Navigation bar HTML
 */
function generateNavBarHTML() {
    const currentPage = getCurrentPage();
    
    // Generate menu items
    const menuItemsHTML = NAV_ITEMS.map(item => {
        const isActive = item.href === currentPage ? 'active' : '';
        return `
            <li class="nav-item">
                <a href="${item.href}" class="nav-link ${isActive}">
                    <span class="nav-icon">${item.icon}</span>
                    <span class="nav-text">${item.label}</span>
                </a>
            </li>
        `;
    }).join('');

    return `
        <div class="nav-header">
            <div class="nav-logo">
                ${ICONS.logo}
                <span class="nav-text">Michelin</span>
            </div>
            <button class="nav-toggle" id="nav-toggle" aria-label="Toggle navigation">
                ${ICONS.hamburger}
            </button>
        </div>
        <ul class="nav-menu">
            ${menuItemsHTML}
        </ul>
        <div class="nav-footer">
            <button class="btn-logout" id="logout-btn">
                <span class="nav-icon">${ICONS.logout}</span>
                <span class="nav-text">Logout</span>
            </button>
        </div>
    `;
}

/**
 * Generate the mobile navigation toggle button HTML
 * @returns {string} Mobile toggle button HTML
 */
function generateMobileToggleHTML() {
    return `
        <button class="mobile-nav-toggle" id="mobile-nav-toggle" aria-label="Open navigation">
            ${ICONS.hamburger}
        </button>
    `;
}

/**
 * Generate the profile icon HTML
 * @param {boolean} isActive - Whether settings page is current
 * @returns {string} Profile icon HTML
 */
function generateProfileIconHTML(isActive = false) {
    const activeClass = isActive ? 'active' : '';
    return `
        <a href="settings.html" class="profile-icon ${activeClass}" title="Settings">
            ${ICONS.profile}
        </a>
    `;
}

/**
 * Initialize the navigation bar by injecting it into the DOM
 */
function initNavigation() {
    const navContainer = document.getElementById('navigation-bar');
    const mobileToggleContainer = document.getElementById('mobile-nav-toggle-container');
    const profileContainer = document.getElementById('profile-icon-container');
    
    // Inject navigation bar
    if (navContainer) {
        navContainer.innerHTML = generateNavBarHTML();
    }
    
    // Inject mobile toggle (create if container doesn't exist)
    if (mobileToggleContainer) {
        mobileToggleContainer.innerHTML = generateMobileToggleHTML();
    } else {
        // Insert mobile toggle after nav if no container exists
        const existingMobileToggle = document.getElementById('mobile-nav-toggle');
        if (!existingMobileToggle && navContainer) {
            const toggleDiv = document.createElement('div');
            toggleDiv.id = 'mobile-nav-toggle-container';
            toggleDiv.innerHTML = generateMobileToggleHTML();
            navContainer.insertAdjacentElement('afterend', toggleDiv);
        }
    }
    
    // Inject profile icon
    if (profileContainer) {
        const isSettingsPage = getCurrentPage() === 'settings.html';
        profileContainer.innerHTML = generateProfileIconHTML(isSettingsPage);
    }
    
    // Attach event listeners
    attachNavigationListeners();
}

/**
 * Attach event listeners to navigation elements
 */
function attachNavigationListeners() {
    // Logout button
    const logoutBtn = document.getElementById('logout-btn');
    if (logoutBtn) {
        logoutBtn.addEventListener('click', handleLogout);
    }
    
    // Nav toggle (collapse/expand)
    const navToggle = document.getElementById('nav-toggle');
    if (navToggle) {
        navToggle.addEventListener('click', toggleNavigation);
    }
    
    // Mobile nav toggle
    const mobileNavToggle = document.getElementById('mobile-nav-toggle');
    if (mobileNavToggle) {
        mobileNavToggle.addEventListener('click', handleMobileNavToggle);
    }
    
    // Window resize handler
    window.addEventListener('resize', handleResize);
}

/**
 * Toggle navigation bar collapsed/expanded state
 */
function toggleNavigation() {
    const navBar = document.getElementById('navigation-bar');
    const mainContent = document.querySelector('main');
    
    if (navBar) {
        navBar.classList.toggle('collapsed');
        if (mainContent) {
            mainContent.classList.toggle('nav-collapsed');
        }
        
        // Store preference in localStorage
        const isCollapsed = navBar.classList.contains('collapsed');
        localStorage.setItem('nav-collapsed', isCollapsed);
    }
}

/**
 * Handle mobile navigation toggle
 */
function handleMobileNavToggle() {
    const navBar = document.getElementById('navigation-bar');
    if (navBar) {
        navBar.classList.toggle('mobile-open');
    }
}

/**
 * Handle logout button click
 */
function handleLogout() {
    // Clear authentication data
    if (window.Auth && typeof window.Auth.logout === 'function') {
        window.Auth.logout();
    } else {
        // Fallback: clear storage and redirect
        localStorage.removeItem('auth_token');
        sessionStorage.removeItem('auth_token');
        window.location.href = 'login.html';
    }
}

/**
 * Handle window resize for responsive navigation
 */
function handleResize() {
    const navBar = document.getElementById('navigation-bar');
    if (navBar && window.innerWidth > 768) {
        navBar.classList.remove('mobile-open');
    }
}

/**
 * Restore navigation state from localStorage
 */
function restoreNavState() {
    const isCollapsed = localStorage.getItem('nav-collapsed') === 'true';
    if (isCollapsed) {
        const navBar = document.getElementById('navigation-bar');
        const mainContent = document.querySelector('main');
        if (navBar) {
            navBar.classList.add('collapsed');
        }
        if (mainContent) {
            mainContent.classList.add('nav-collapsed');
        }
    }
}

/**
 * Update profile icon with user's picture
 * @param {string} imageUrl - Profile picture URL
 */
function updateProfileIcon(imageUrl) {
    const profileIcon = document.querySelector('.profile-icon');
    if (profileIcon && imageUrl) {
        profileIcon.innerHTML = `<img src="${imageUrl}" alt="Profile" class="profile-img">`;
    }
}

